import{_ as e,c as r,o as i,af as n}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"35、【晉】 坤下離上","description":"溫公易說 - 35、【晉】 坤下離上","frontmatter":{"title":"35、【晉】 坤下離上","description":"溫公易說 - 35、【晉】 坤下離上"},"headers":[],"relativePath":"classics/wengong/036.md","filePath":"classics/wengong/036.md"}'),l={name:"classics/wengong/036.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_35、【晉】-坤下離上" tabindex="-1">35、【晉】 坤下離上 <a class="header-anchor" href="#_35、【晉】-坤下離上" aria-label="Permalink to “35、【晉】 坤下離上”">​</a></h1><h3 id="彖曰-晉-進也。明出地上-順而麗乎大明。柔進而上行-是以康侯用錫馬蕃庶-晝日三接也。" tabindex="-1">彖曰：晉，進也。明出地上，順而麗乎大明。柔進而上行，是以康侯用錫馬蕃庶，晝日三接也。 <a class="header-anchor" href="#彖曰-晉-進也。明出地上-順而麗乎大明。柔進而上行-是以康侯用錫馬蕃庶-晝日三接也。" aria-label="Permalink to “彖曰：晉，進也。明出地上，順而麗乎大明。柔進而上行，是以康侯用錫馬蕃庶，晝日三接也。”">​</a></h3><h3 id="象曰-明出地上-晉。君子以自昭明德。" tabindex="-1">象曰：明出地上，晉。君子以自昭明德。 <a class="header-anchor" href="#象曰-明出地上-晉。君子以自昭明德。" aria-label="Permalink to “象曰：明出地上，晉。君子以自昭明德。”">​</a></h3><p>君子進其明德，如日之升也。</p><h3 id="初六-晉如摧如-貞吉。罔孚裕無咎-象曰-晉如摧如-獨行正也。裕無咎-未受命也。" tabindex="-1">初六：晉如摧如，貞吉。罔孚裕無咎 象曰：晉如摧如，獨行正也。裕無咎，未受命也。 <a class="header-anchor" href="#初六-晉如摧如-貞吉。罔孚裕無咎-象曰-晉如摧如-獨行正也。裕無咎-未受命也。" aria-label="Permalink to “初六：晉如摧如，貞吉。罔孚裕無咎 象曰：晉如摧如，獨行正也。裕無咎，未受命也。”">​</a></h3><p>初進者德業未著，人莫之信。躁以求之則兇，寬以待之無咎。未受命者，受上命然後可進，無命而進兇道也。</p><h3 id="六二-晉如愁如-貞吉。受茲介福於其王母-象曰-受茲介福-以中正也。" tabindex="-1">六二：晉如愁如，貞吉。受茲介福於其王母 象曰：受茲介福，以中正也。 <a class="header-anchor" href="#六二-晉如愁如-貞吉。受茲介福於其王母-象曰-受茲介福-以中正也。" aria-label="Permalink to “六二：晉如愁如，貞吉。受茲介福於其王母 象曰：受茲介福，以中正也。”">​</a></h3><h3 id="六三-眾允悔亡-象曰-眾允之志-上行也。" tabindex="-1">六三：眾允悔亡 象曰：眾允之志，上行也。 <a class="header-anchor" href="#六三-眾允悔亡-象曰-眾允之志-上行也。" aria-label="Permalink to “六三：眾允悔亡 象曰：眾允之志，上行也。”">​</a></h3><h3 id="九四-晉如鼫鼠-貞厲-象曰-鼫鼠貞厲-位不當也。" tabindex="-1">九四：晉如鼫鼠，貞厲 象曰：鼫鼠貞厲，位不當也。 <a class="header-anchor" href="#九四-晉如鼫鼠-貞厲-象曰-鼫鼠貞厲-位不當也。" aria-label="Permalink to “九四：晉如鼫鼠，貞厲 象曰：鼫鼠貞厲，位不當也。”">​</a></h3><h3 id="六五-悔亡-失得勿恤-往吉無不利-象曰-失得勿恤-往有慶也。" tabindex="-1">六五：悔亡，失得勿恤，往吉無不利 象曰：失得勿恤，往有慶也。 <a class="header-anchor" href="#六五-悔亡-失得勿恤-往吉無不利-象曰-失得勿恤-往有慶也。" aria-label="Permalink to “六五：悔亡，失得勿恤，往吉無不利 象曰：失得勿恤，往有慶也。”">​</a></h3><h3 id="上九-晉其角-維用伐邑-厲吉無咎-貞吝-象曰-維用伐邑-道未光也。" tabindex="-1">上九：晉其角，維用伐邑，厲吉無咎，貞吝 象曰：維用伐邑，道未光也。 <a class="header-anchor" href="#上九-晉其角-維用伐邑-厲吉無咎-貞吝-象曰-維用伐邑-道未光也。" aria-label="Permalink to “上九：晉其角，維用伐邑，厲吉無咎，貞吝 象曰：維用伐邑，道未光也。”">​</a></h3>',11)])])}const f=e(l,[["render",t]]);export{b as __pageData,f as default};
